const engineering = JSON.parse(
  readFileSync(new URL("../../packages/github/test/fixtures/engineering.json", import.meta.url), "utf8"),
);
export const notesMergeTime = "2026-10-07T10:00:00.000Z";
export const notesReviewTime = "2026-10-09T10:00:00.000Z";
export const notesCutoff = "2026-10-10T10:00:00.000Z";
export const notesRevision = "c".repeat(40);
export const notesCandidate = "documentation_purpose_candidate:release_notes";
export const notesPurpose = "documentation_purpose:release_notes";
