export function refreshAuthoredNotesReview(
  s,
  references = [{ locator: s.evidence.sourceRevisionUrl, revision: s.evidence.sourceRevision }],
) {
  s.request.detail = JSON.stringify(s.purpose);
  s.record.requestId = s.request.id;
  s.record.requestVersion = s.request.version;
  s.record.decisionId = s.decision.id;
  s.decision.receipt = s.request.id;
  attachSyntheticEvidenceIntake(s.request, { sourceUseReview: { references } });
  s.state.audit = [structuredClone(s.decision)];
}
export function authoredNotesReceipt(s) {
  return {
    id: s.decision.id,
    verified: true,
    targetFactId: s.target.id,
    metricId: "documentation",
    actorId: s.target.actorId,
    reviewerId: s.decision.actor,
    acceptedAt: notesReviewTime,
    decision: "accepted",
    evidenceIds: [s.target.id],
    sourceRevision: s.evidence.sourceRevision,
    documentationPurpose: "release_notes",
  };
}
export const materializeAuthoredNotes = (s, callback = applyRecognitionReceipt) =>
  materializeRecognition(s.input, s.state, [s.binding], s.policies, callback, notesCutoff, publicDocumentationReasons);
export function authoredNotesProof(output) {
  const facts = output.facts.filter((fact) => fact.metricId === "documentation" && fact.state === "qualified");
  assert.equal(facts.length, 1);
  return {
    fact: facts[0],
    evidence: output.evidence.find((entry) => entry.contribution.contributionId === facts[0].id),
  };
}
